#!/bin/bash
set -euo pipefail
source "$(dirname "$0")/env.sh"
cd "$DEPS_SRC/OpenSceneGraph-OpenSceneGraph-3.4.1"
cmake -S . -B build-ios "${ios_cmake_common[@]}" \
  -DBUILD_SHARED_LIBS=OFF -DDYNAMIC_OPENSCENEGRAPH=OFF -DDYNAMIC_OPENTHREADS=OFF \
  -DOPENGL_PROFILE=GL2 -DOSG_OSX_SDK_NAME=macosx10.6 -DOPENTHREADS_ATOMIC_USE_MUTEX=ON \
  -DOPENGL_INCLUDE_DIR="$DEPS_INCLUDE" -DOPENGL_gl_LIBRARY="$DEPS_LIB/libGL.a" \
  -DOPENGL_HEADER1="#include <GL/gl.h>" -DOPENGL_HEADER2="" \
  -DFREETYPE_INCLUDE_DIRS="$DEPS_INCLUDE/freetype2" -DFREETYPE_LIBRARY="$DEPS_LIB/libfreetype.a" \
  -DJPEG_INCLUDE_DIR="$DEPS_INCLUDE" -DJPEG_LIBRARY="$DEPS_LIB/libjpeg.a" \
  -DPNG_PNG_INCLUDE_DIR="$DEPS_INCLUDE" -DPNG_LIBRARY="$DEPS_LIB/libpng16.a" \
  -DZLIB_INCLUDE_DIR="$DEPS_INCLUDE" -DZLIB_LIBRARY="$DEPS_LIB/libz.a" \
  -DBUILD_OSG_APPLICATIONS=OFF -DBUILD_OSG_EXAMPLES=OFF -DBUILD_DOCUMENTATION=OFF \
  -DCMAKE_C_FLAGS="$CFLAGS -I$DEPS_INCLUDE -I$DEPS_INCLUDE/freetype2" \
  -DCMAKE_CXX_FLAGS="$CXXFLAGS -I$DEPS_INCLUDE -I$DEPS_INCLUDE/freetype2"
cmake --build build-ios -j"${OSG_JOBS:-2}"
cmake --install build-ios
